/* ============ G01 SEARCH; K SETTINGS; B PREMIUM; S HELP ============ */
const hl=(s,q)=>{s=esc(s);if(!q)return s;const i=s.toLowerCase().indexOf(q.toLowerCase());return i<0?s:s.slice(0,i)+`<mark class="hl">${s.slice(i,i+q.length)}</mark>`+s.slice(i+q.length);};
function searchData(q,f){q=q.toLowerCase().trim();const has=s=>String(s||'').toLowerCase().includes(q);
 const people=Object.keys(PEOPLE).filter(id=>!isBlocked(id)&&(has(pname(id))||has(id)||has(PEOPLE[id].name)));
 const posts=filterPosts(allPosts(),f.posts||{}).filter(p=>has(T(p.text))||p.tags.some(t=>has(topic(t))));
 const groups=Object.keys(COMMUNITIES).filter(c=>!COMMUNITIES[c].hidden&&(has(T(COMMUNITIES[c].name))||has(mdPlain(T(COMMUNITIES[c].desc)))||COMMUNITIES[c].topics.some(t=>has(topic(t))))&&(!(f.groups||{}).privacy||f.groups.privacy==='all'||COMMUNITIES[c].privacy===f.groups.privacy));
 const ef=Object.assign(EF_DEF(),f.events||{});const events=evFiltered(ef).filter(id=>has(T(EV(id).title))||has(mdPlain(T(EV(id).desc)))||has(pname(EV(id).organizer)));
 const topics=Object.keys(TOPICS).filter(t=>has(topic(t))||has(TOPICS[t].en)||has(TOPICS[t].ru));
 return{people,posts,groups,events,topics};}
SC.G01={title:()=>L('Поиск','Search'),render:(p,r)=>{const scope=p.scope||'all';const q=r.f.q??p.q??'';r.f.q=q;S.filters.search=S.filters.search||{};const f=S.filters.search;
 const tabs=tabsRow([['all',L('Всё','All')],['people',L('Люди','People')],['posts',L('Публикации','Posts')],['groups',L('Сообщества','Communities')],['events',L('События','Events')],['topics',L('Интересы','Interests')]],scope,'gScope');
 const fn=scope==='posts'?filtN(f.posts||{}):scope==='events'?efCount(Object.assign(EF_DEF(),f.events||{}))+((f.events||{}).format&&f.events.format!=='all'?1:0):scope==='groups'?((f.groups||{}).privacy&&f.groups.privacy!=='all'?1:0):0;
 const fbtn=['posts','events','groups'].includes(scope)?`<button class="chip filter ${fn?'on':''}" data-act="gFilters">${ic('filter',16)}${L('Фильтры','Filters')}${fn?`<em class="badge-abs">${fn}</em>`:''}</button>`:'';
 let body='';
 if(q.trim().length<2){body=`${q.trim().length===1?`<p class="note">${L('Введи хотя бы 2 символа','Type at least 2 characters')}</p>`:''}${S.searchRecent.length?`<div class="res-h">${L('Недавние','Recent')}<button data-act="gClearRecent">${L('Очистить','Clear')}</button></div><div class="card list">${S.searchRecent.map(x=>`<div class="recent">${I.hist}<button class="tx" style="text-align:left" data-act="gUse" data-v="${esc(x)}">${esc(x)}</button><button class="ibtn ghost sm" data-act="gRm" data-v="${esc(x)}" aria-label="${L('Удалить','Remove')}">${I.close}</button></div>`).join('')}</div>`:''}
  <div class="res-h">${L('Популярные интересы','Popular interests')}</div><div class="chips">${['shibari','aftercare','talk','slow','latex'].map(t=>`<button class="chip" data-act="gUse" data-v="${esc(topic(t))}">#${esc(topic(t))}</button>`).join('')}</div>
  ${scope==='people'?`<div class="alert info mt16">${I.info}<span>${L('Людей ищем по нику и имени — даже если у них выключены знакомства. Фильтры по возрасту, расстоянию и интересам есть только в разделе «Люди».','People are found by nickname and name — even with dating off. Age, distance and interest filters live only in People.')}</span></div>`:''}`;}
 else{const d=searchData(q,f);const sec=(k,title,items,render,limit)=>items.length?`<div class="res-h">${title} · ${items.length}${scope==='all'&&items.length>limit?`<button data-act="gScope" data-v="${k}">${L('Все','See all')}</button>`:''}</div>${render(scope==='all'?items.slice(0,limit):items)}`:'';
  const R={people:x=>`<div class="card list">${x.map(id=>`<button class="li" data-go="P01" data-id="${id}">${av(id,'')}<span class="tx"><b>${hl(pname(id),q)}${person(id).age?', '+person(id).age:''}</b><small>@${esc(id)} · ${esc(city(person(id).city))}</small></span>${I.chev}</button>`).join('')}</div>`,
   posts:x=>`<div class="posts">${x.map((p2,i)=>postCard(p2,{i})).join('')}</div>`,groups:x=>x.map((c,i)=>commCard(c,{i})).join(''),events:x=>x.map(id=>eventCard(id,{row:1})).join('<div style="height:8px"></div>'),
   topics:x=>`<div class="card list">${x.map(t=>`<button class="topic-row" data-act="topic" data-v="${t}"><span class="ico v">${I.book}</span><span class="tx"><b>${hl(topic(t),q)}</b><small>${esc(T(CATS.find(c=>c.id===TOPICS[t].cat)))}</small></span>${I.chev}</button>`).join('')}</div>`};
  const order=scope==='all'?['people','groups','events','topics','posts']:[scope];
  const names={people:L('Люди','People'),posts:L('Публикации','Posts'),groups:L('Сообщества','Communities'),events:L('События','Events'),topics:L('Интересы','Interests')};
  body=order.map(k=>sec(k,names[k],d[k],R[k],3)).join('')||empty('search',L('Ничего не нашлось','Nothing found'),fn?L('Попробуй снять фильтры или изменить запрос.','Try removing filters or changing the query.'):L('Проверь написание — ищем по-русски и по-английски.','Check the spelling — we search in Russian and English.'),fn?`<button class="btn soft" data-act="gReset">${L('Сбросить фильтры','Reset filters')}</button>`:'');}
 return `<div class="sbar"><button class="ibtn ghost" data-back aria-label="${L('Назад','Back')}">${I.back}</button><div class="inwrap">${I.search}<input class="inp" id="gq" type="search" placeholder="${L('Ник, тема, событие…','Nickname, topic, event…')}" value="${esc(q)}" data-in="gq" data-enter="gCommit" autofocus enterkeyhint="search"></div></div>
 <div class="view nodock"><div class="wrap">${tabs}${fbtn?`<div class="search-tools"><span class="note">${L('Поиск в выбранном разделе','Search in this section')}</span>${fbtn}</div>`:''}${body}</div></div>`;},after:(p,r)=>{if(r.focused)return;r.focused=1;const i=$('#gq');if(i&&!i.value&&document.activeElement!==i)i.focus({preventScroll:true});}};
let gqT;IN.gq=el=>{cur().f.q=el.value;clearTimeout(gqT);gqT=setTimeout(()=>{if(cur().id!=='G01')return;const pos=el.selectionStart;refresh();const n=$('#gq');n.focus();n.setSelectionRange(pos,pos);},220);};
ACT.gCommit=()=>{const q=(cur().f.q||'').trim();if(q.length>=2&&!S.searchRecent.includes(q)){S.searchRecent.unshift(q);S.searchRecent=S.searchRecent.slice(0,6);}};
ACT.gScope=a=>{ACT.gCommit();cur().p.scope=a.dataset.v;refresh();};
ACT.gUse=a=>{cur().f.q=a.dataset.v;refresh();};
ACT.gRm=a=>{S.searchRecent=S.searchRecent.filter(x=>x!==a.dataset.v);refresh();};
ACT.gClearRecent=()=>{S.searchRecent=[];refresh();};
ACT.gReset=()=>{S.filters.search={};refresh();};
ACT.gFilters=()=>{const scope=cur().p.scope;const f=S.filters.search;
 if(scope==='events'){S.ui.efTarget='search';ACT.evFilters(null,null,JSON.parse(JSON.stringify(Object.assign(EF_DEF(),f.events||{}))));return;}
 if(scope==='posts'){S.ui.ff={fk:'__search',d:Object.assign({tags:[],ex:[],types:[]},JSON.parse(JSON.stringify(f.posts||{})))};const TI=topicItems();
  filterSheet({title:L('Фильтры публикаций','Post filters'),draft:()=>S.ui.ff.d,count:()=>1,applyLabel:()=>L('Применить','Apply'),reset:()=>{S.ui.ff.d={tags:[],ex:[],types:[]};},apply:()=>{S.filters.search.posts=S.ui.ff.d;},
   rows:[{k:'types',label:L('Что в публикации','Post contains'),on:()=>S.ui.ff.d.types.length,summary:()=>sumOf(TYPES(),S.ui.ff.d.types,L('Всё','Anything')),body:()=>fChips(TYPES(),S.ui.ff.d.types,'ffType')},{k:'tags',label:L('Интересы','Interests'),search:1,pick:()=>({items:TI,sel:S.ui.ff.d.tags,act:'ffTag',groups:topicGroups()}),on:()=>S.ui.ff.d.tags.length,summary:()=>sumOf(TI,S.ui.ff.d.tags,L('Все интересы','All interests')),body:()=>fChips(TI,S.ui.ff.d.tags,'ffTag',{groups:topicGroups()})}]});return;}
 if(scope==='groups'){S.ui.cf={privacy:'all',...(f.groups||{})};const PR=()=>[['all',L('Любые','Any')],['open',L('Открытые','Open')],['closed',L('По заявке','By request')]];
  filterSheet({title:L('Фильтры сообществ','Community filters'),draft:()=>S.ui.cf,count:()=>1,applyLabel:()=>L('Применить','Apply'),reset:()=>{S.ui.cf={privacy:'all'};},apply:()=>{S.filters.search.groups=S.ui.cf;},
   rows:[{k:'privacy',label:L('Вступление','Joining'),on:()=>S.ui.cf.privacy!=='all',summary:()=>PR().find(x=>x[0]===S.ui.cf.privacy)[1],body:()=>grp('',choices(PR(),S.ui.cf.privacy,'cfSet'))}]});}};
ACT.gfPostsApply=()=>{S.filters.search.posts=S.ui.ff.d;closeSheet();refresh();};
ACT.gfGroupsApply=()=>{S.filters.search.groups=S.ui.cf;closeSheet();refresh();};


/* K01 — settings */
SC.K01={title:()=>L('Настройки','Settings'),render:()=>{const m=S.me;return `${bar(L('Настройки','Settings'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">
 <div class="sec" style="margin-top:4px">${L('Аккаунт','Account')}</div><div class="card list">${linkRow({go:'K06',icon:'key',title:L('Вход и безопасность','Sign-in & security'),sub:m.email||L('почта не указана','no email')})}${linkRow({act:'ageFromMe',icon:'shield',tone:m.ageCheck==='ok'?'g':'a',title:L('Проверка возраста','Age check'),val:{ok:L('подтверждено','verified'),pending:L('проверяется','in progress'),none:L('не пройдена','not done')}[m.ageCheck]})}${linkRow({go:'V01',icon:'verified',tone:'v',title:L('Фото-верификация','Photo verification'),val:{ok:L('подтверждено','verified'),pending:L('проверяется','in review'),rejected:L('не прошла','failed'),none:L('не пройдена','not done')}[m.photoCheck||'none']})}${linkRow({go:'B01',icon:'crown',tone:'l',title:'Premium',val:m.premium?L('активен','active'):L('не подключён','not active')})}</div>
 <div class="sec">${L('Приложение','App')}</div><div class="card list">${linkRow({go:'K02',icon:'globe',title:L('Язык','Language'),val:S.lang==='en'?'English':'Русский'})}${linkRow({go:'K03',icon:'moon',title:L('Тема оформления','Appearance'),val:{light:L('светлая','light'),dark:L('тёмная','dark'),auto:L('системная','system')}[themePref()]})}${linkRow({go:'K05',icon:'bell',title:L('Уведомления','Notifications')})}</div>
 <div class="sec">${L('Приватность','Privacy')}</div><div class="card list">${linkRow({go:'K04',icon:'eye',tone:'v',title:L('Приватность и знакомства','Privacy & dating'),sub:m.dating?L('знакомства включены','dating on'):L('знакомства выключены','dating off')})}${linkRow({go:'P12',icon:'block',title:L('Заблокированные','Blocked'),val:String(S.blocked.length)})}${linkRow({go:'K07',icon:'download',title:L('Мои данные и удаление','Your data & deletion')})}</div>
 <div class="sec">${L('Поддержка','Support')}</div><div class="card list">${linkRow({go:'S01',icon:'help',title:L('Помощь и безопасность','Help & safety')})}${linkRow({act:'logout',icon:'logout',cls:'danger',title:L('Выйти','Sign out'),noChev:1})}</div>
 <p class="note center mt24">FetUre · V6 · ${L('прототип интерфейса','interface prototype')}</p></div></div>`;}};
ACT.logout=()=>ask({icon:'logout',title:L('Выйти из аккаунта?','Sign out?'),text:L('На этом устройстве не останется твоих данных. Войти можно в любой момент.','None of your data stays on this device. You can sign in any time.'),ok:L('Выйти','Sign out'),danger:true}).then(ok=>{if(ok)restartPrototype();});
SC.K02={title:()=>L('Язык','Language'),render:()=>`${bar(L('Язык','Language'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">${[['system',L('Как в системе','System default'),L('Системный язык устройства','Device language')],['ru','Русский',''],['en','English','']].map(([k,t,s])=>`<button class="radio ${(S.langPref||'ru')===k?'on':''}" data-act="k2" data-v="${k}"><i></i><span class="tx"><b>${t}</b>${s?`<small>${s}</small>`:''}</span></button>`).join('')}<p class="note mt16">${L('Это язык интерфейса, писем и уведомлений. Публикации людей не переводятся автоматически.','This is the language of the interface, emails and notifications. People’s posts aren’t auto-translated.')}</p></div></div>`};
ACT.k2=a=>{S.langPref=a.dataset.v;S.lang=a.dataset.v==='system'?(navigator.language.toLowerCase().startsWith('ru')?'ru':'en'):a.dataset.v;document.documentElement.lang=S.lang;refresh();toast(S.lang==='en'?'Language: English':'Язык: русский',{type:'ok'});};
const themePref=()=>{try{return localStorage.getItem('feture-v6-theme')||'auto'}catch(e){return 'auto'}};
function applyTheme(t){const r=document.documentElement;if(t==='auto')r.removeAttribute('data-theme');else r.setAttribute('data-theme',t);try{localStorage.setItem('feture-v6-theme',t)}catch(e){}window.QA_SYNC&&QA_SYNC();}
SC.K03={title:()=>L('Тема','Appearance'),render:()=>`${bar(L('Тема оформления','Appearance'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><div class="cats" style="grid-template-columns:repeat(3,1fr)">${[['light',L('Светлая','Light'),'#F3EEF2','#fff','#1E1219'],['dark',L('Тёмная','Dark'),'#1A0F16','#241520','#FBF0F4'],['auto',L('Системная','System'),'linear-gradient(90deg,#F3EEF2 50%,#1A0F16 50%)','#fff','#1E1219']].map(([k,t,bg,sf,ink])=>`<button data-act="k3" data-v="${k}" style="display:grid;gap:8px;justify-items:center;padding:10px;border-radius:20px;border:2px solid ${themePref()===k?'var(--latex)':'var(--line)'};background:var(--surf)"><span style="width:100%;aspect-ratio:3/4;border-radius:14px;background:${bg};display:grid;align-content:end;padding:8px;gap:5px"><i style="height:10px;border-radius:5px;background:${sf}"></i><i style="height:10px;width:60%;border-radius:5px;background:#E01A3E"></i></span><b style="font-size:13.5px">${t}</b></button>`).join('')}</div><p class="note mt16">${L('Системная тема переключается вместе с телефоном, без перезапуска.','System follows your phone automatically, no restart needed.')}</p></div></div>`};
ACT.k3=a=>{applyTheme(a.dataset.v);refresh();};
SC.K04={title:()=>L('Приватность','Privacy'),render:()=>{const m=S.me;return `${bar(L('Приватность и знакомства','Privacy & dating'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">
 <div class="sec" style="margin-top:4px">${L('Знакомства','Dating')}</div><div class="card list">${m.dating?toggleRow('k4vis',L('Показывать меня в подборке','Show me in Discover'),m.datingVisible?L('Выключи, чтобы смотреть незаметно — совпадения и чаты останутся','Turn off to browse hidden — matches and chats stay'):L('Сейчас ты смотришь незаметно','You’re browsing hidden now'),m.datingVisible):''}${m.dating?linkRow({act:'k4off',icon:'heart',tone:'l',title:L('Выключить знакомства','Turn off dating'),sub:L('Обычный профиль и чаты сохранятся','Your profile and chats stay'),noChev:1}):linkRow({act:'enableDating',icon:'heart',tone:'l',title:L('Включить знакомства','Turn on dating')})}${toggleRow('k4social',L('Принимать симпатии из профиля','Accept likes from my profile'),L('Даже когда знакомства выключены','Even when dating is off'),m.socialLikes)}</div>
 <div class="sec">${L('Расширенный профиль','Private profile')}</div><div class="card list">${linkRow({go:'P04',icon:'lock',tone:'v',title:L('Кто может запрашивать','Who can request'),val:{all:L('все','everyone'),matches:L('совпадения','matches'),none:L('никто','nobody')}[m.requestsFrom]})}${linkRow({go:'P07',p:{tab:'byme'},icon:'unlock',title:L('Кому открыто','Shared by me'),val:String(givenGrantEntries().length)})}</div>
 <div class="sec">${L('События','Events')}</div><div class="card list">${toggleRow('k4rsvp',L('Показывать моё участие по умолчанию','Show my attendance by default'),L('Можно изменить для каждого события','You can change it per event'),m.rsvpShow)}</div>
 <div class="sec">${L('Чаты','Chats')}</div><div class="card list">${toggleRow('k4blur',L('Размывать входящие фото и видео','Blur incoming photos and video'),L('Пока не нажмёшь, содержимое не видно. Сейчас размываются все входящие; распознавать только откровенные мы пока не умеем.','Nothing shows until you tap. For now all incoming media is blurred; we can’t yet detect only explicit content.'),m.chatBlur!==false)}</div>
 <div class="sec">${L('Контакты','Contacts')}</div><div class="card list">${linkRow({go:'P12',icon:'block',title:L('Заблокированные','Blocked'),val:String(S.blocked.length)})}</div>
 <p class="note mt12">${L('Все настройки приватности бесплатны и действуют сразу.','All privacy settings are free and take effect immediately.')}</p></div></div>`;}};
ACT.k4blur=()=>{S.me.chatBlur=S.me.chatBlur===false;refresh();toast(S.me.chatBlur!==false?L('Входящие фото и видео размываются','Incoming photos and video are blurred'):L('Входящие фото и видео показываются сразу','Incoming photos and video show right away'));};
ACT.k4vis=a=>{if(!S.me.datingVisible&&!S.me.photo){toast(L('Чтобы показаться в подборке, добавь фото','Add a photo to appear in Discover'),{type:'warn',action:{label:L('Добавить','Add'),fn:()=>go('P02')}});return;}run(null,()=>{S.me.datingVisible=!S.me.datingVisible;refresh();},{ms:300,ok:()=>S.me.datingVisible?L('Ты снова в подборке','You’re back in Discover'):L('Ты смотришь незаметно','You’re browsing hidden')});};
ACT.k4social=()=>run(null,()=>{S.me.socialLikes=!S.me.socialLikes;refresh();},{ms:300,ok:L('Сохранено','Saved')});
ACT.k4rsvp=()=>run(null,()=>{S.me.rsvpShow=!S.me.rsvpShow;refresh();},{ms:300,ok:L('Сохранено','Saved')});
ACT.k4off=()=>ask({icon:'heart',tone:'l',title:L('Выключить знакомства?','Turn off dating?'),text:L('Ты пропадёшь из подборки и перестанешь видеть анкеты. Совпадения, чаты и выданные доступы останутся.','You’ll disappear from Discover and stop seeing profiles. Matches, chats and shared access stay.'),ok:L('Выключить','Turn off'),danger:true}).then(ok=>{if(ok)run(null,()=>{S.me.dating=false;S.me.datingVisible=false;refresh();},{ok:L('Знакомства выключены','Dating is off')});});
/* K05 — V7 notifications: safe mode by default, push + email channels per category, quiet hours and email digest */
const NOTIF_CATS=()=>[['match',I.chat,L('Совпадения и сообщения','Matches & messages'),L('Взаимная симпатия, новое сообщение','A mutual like, a new message')],['likes',I.heart,L('Новые симпатии','New likes'),L('Собираем вместе, не чаще раза в час','Grouped, at most hourly')],['req',I.key,L('Запросы и доступы','Requests & access'),L('Кто-то просит открыть приватное, тебе открыли доступ','Someone asks for private sections, access shared with you')],['events',I.cal,L('События','Events'),L('Изменения, отмены, напоминания за день','Changes, cancellations, day-before reminders')],['replies',I.feed,L('Ответы и реакции','Replies & reactions'),L('Ответы на твои публикации и обсуждения','Replies to your posts and discussions')],['follows',I.users3,L('Новые подписчики','New followers'),L('Кто подписывается на твои публикации','Who starts following your posts')],['groups',I.groups,L('Сообщества','Communities'),L('Объявления ведущих, решения по заявке','Host announcements, join decisions')],['news',I.spark,L('Новости FetUre','FetUre news'),L('Новые функции — не чаще раза в месяц','New features — at most monthly')]];
function notifDefaults(){return{mode:'safe',push:true,email:true,digest:'daily',quiet:true,from:'23:00',to:'08:00',cat:{match:{push:1,email:1},likes:{push:1,email:0},req:{push:1,email:1},events:{push:1,email:1},replies:{push:1,email:0},follows:{push:1,email:0},groups:{push:0,email:0},news:{push:0,email:1}}};}
SC.K05={title:()=>L('Уведомления','Notifications'),render:(p,r)=>{const n=S.me.notif||(S.me.notif=notifDefaults());const safe=n.mode==='safe';
 const lock=(t,b)=>`<div class="lockscreen"><span class="ls-app"><img src="${LOGO()}" alt="">${safe?L('Уведомление','Notification'):'FetUre'}</span><b>${t}</b><span>${b}</span><small>${L('сейчас','now')}</small></div>`;
 return `${bar(L('Уведомления','Notifications'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">
 <div class="sec" style="margin-top:4px">${L('Что видно на экране блокировки','What shows on the lock screen')}</div>
 <div class="nmode">${[['safe',L('Безопасные','Discreet'),L('Без имён, текста и названия приложения. Подробности — только внутри FetUre.','No names, text or app name. Details only inside FetUre.')],['normal',L('Обычные','Regular'),L('С именем и началом сообщения — удобно, но видно всем рядом.','With the name and message preview — handy, but visible to anyone nearby.')]].map(([k,t,d])=>`<button class="nm ${n.mode===k?'on':''}" data-act="k5mode" data-v="${k}" aria-pressed="${n.mode===k}"><span class="rd"></span><b>${t}${k==='safe'?`<em>${L('по умолчанию','default')}</em>`:''}</b><small>${d}</small></button>`).join('')}</div>
 ${lock(safe?L('Новое уведомление','New notification'):'Mia',safe?L('Открой приложение, чтобы посмотреть','Open the app to see it'):L('Привет! Увидела, что у нас совпали…','Hi! Saw we matched on…'))}
 <div class="sec">${L('Куда присылать','Where to send')}</div>
 <div class="card list">${toggleRow('k5ch',L('Пуш на телефон','Push to phone'),L('Можно выключить в любой момент','Turn off any time'),n.push,'data-v="push"')}${toggleRow('k5ch',L('Письма на почту','Email'),esc(S.me.email||L('почта не указана','no email')),n.email,'data-v="email"')}</div>
 ${n.email?`<div class="chips mt8">${[['instant',L('Сразу','Instantly')],['daily',L('Раз в день','Daily digest')],['weekly',L('Раз в неделю','Weekly')]].map(([k,l])=>chipBtn(k,l,n.digest===k,'k5digest')).join('')}</div><p class="note mt8">${L('Письма всегда нейтральные: тема «Новости твоего аккаунта», без имён и текста — подробности только в приложении.','Emails are always discreet: subject “Your account updates”, no names or text — details only in the app.')}</p>`:''}
 <div class="sec">${L('О чём сообщать','What to notify about')}<span class="nhead">${ic('phone',14)}${ic('mail',14)}</span></div>
 <div class="card list ncats">${NOTIF_CATS().map(([k,i,t,d])=>{const c=n.cat[k]||(n.cat[k]={...notifDefaults().cat[k]});return `<div class="li"><span class="ico">${i}</span><span class="tx"><b>${t}</b><small>${d}</small></span><button class="nt-t ${c.push&&n.push?'on':''}" data-act="k5cat" data-v="${k}" data-c="push" ${n.push?'':'disabled'} aria-pressed="${!!c.push}" aria-label="${L('Пуш','Push')}: ${t}">${I.phone}</button><button class="nt-t ${c.email&&n.email?'on':''}" data-act="k5cat" data-v="${k}" data-c="email" ${n.email?'':'disabled'} aria-pressed="${!!c.email}" aria-label="${L('Почта','Email')}: ${t}">${I.mail}</button></div>`;}).join('')}</div>
 <div class="sec">${L('Тихие часы','Quiet hours')}</div>
 <div class="card list">${toggleRow('k5quiet',L(`Не беспокоить ${n.from}–${n.to}`,`Do not disturb ${n.from}–${n.to}`),L('Пуши придут утром одним сообщением. По твоему часовому поясу','Pushes arrive in the morning as one message. Your time zone'),n.quiet)}</div>
 <p class="note mt12">${L('Уведомления безопасности аккаунта (вход с нового устройства, удаление) приходят всегда — в безопасном виде.','Account security alerts (new sign-in, deletion) always come through — discreetly.')}</p></div></div>`;}};
const k5=()=>S.me.notif;
ACT.k5mode=a=>{k5().mode=a.dataset.v;refresh();toast(a.dataset.v==='safe'?L('Безопасные уведомления: без имён и текста','Discreet notifications: no names or text'):L('Обычные уведомления: с именем и текстом','Regular notifications: with name and text'),{type:'ok'});};
ACT.k5ch=a=>{const n=k5();n[a.dataset.v]=!n[a.dataset.v];refresh();};
ACT.k5digest=a=>{k5().digest=a.dataset.v;refresh();};
ACT.k5cat=a=>{const c=k5().cat[a.dataset.v];c[a.dataset.c]=c[a.dataset.c]?0:1;refresh();};
ACT.k5quiet=()=>{k5().quiet=!k5().quiet;refresh();};
SC.K06={title:()=>L('Вход и безопасность','Sign-in & security'),render:()=>{const m=S.me;const has=k=>m.methods.includes(k);return `${bar(L('Вход и безопасность','Sign-in & security'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">
 <div class="sec" style="margin-top:4px">${L('Способы входа','Sign-in methods')}</div><div class="card list">
  <div class="li"><span class="ico">${I.mail}</span><span class="tx"><b>${L('Почта','Email')}</b><small>${esc(m.email||'—')}</small></span><span class="pill ok">${L('основной','primary')}</span></div>
  <div class="li"><span class="ico">${I.google}</span><span class="tx"><b>Google</b><small>${has('google')?'alex.b@gmail.com':L('не подключён','not linked')}</small></span><button class="btn sm ${has('google')?'soft':'primary'}" data-act="k6link" data-v="google">${has('google')?L('Отвязать','Unlink'):L('Подключить','Link')}</button></div>
  <div class="li"><span class="ico">${I.apple}</span><span class="tx"><b>Apple</b><small>${has('apple')?L('подключён','linked'):L('не подключён','not linked')}</small></span><button class="btn sm ${has('apple')?'soft':'primary'}" data-act="k6link" data-v="apple">${has('apple')?L('Отвязать','Unlink'):L('Подключить','Link')}</button></div></div>
 <div class="sec">${L('Активные сессии','Active sessions')}</div><div class="card list"><div class="li"><span class="ico g">${I.phone}</span><span class="tx"><b>${L('Это устройство','This device')}</b><small>Android · ${city('berlin')} · ${L('сейчас','now')}</small></span></div>${S.ui.sessKilled?'':`<div class="li"><span class="ico">${I.globe}</span><span class="tx"><b>Chrome · Windows</b><small>${city('berlin')} · ${L('2 дня назад','2 days ago')}</small></span><button class="btn sm danger" data-act="k6kill">${L('Завершить','End')}</button></div>`}</div>
 <p class="note mt12">${L('Пароля нет: вход по коду из письма или через Apple/Google. Если увидишь незнакомую сессию — заверши её.','No password: sign in with an email code or Apple/Google. If you see an unknown session, end it.')}</p></div></div>`;}};
ACT.k6link=a=>{const k=a.dataset.v;const m=S.me;if(m.methods.includes(k)){if(m.methods.length<=1&&!m.email){toast(L('Это единственный способ входа — сначала добавь другой','This is your only sign-in method — add another first'),{type:'err'});return;}run(a,()=>{m.methods=m.methods.filter(x=>x!==k);refresh();},{ok:L('Отвязано','Unlinked')});}else run(a,()=>{m.methods.push(k);refresh();},{ms:900,ok:L('Подключено','Linked')});};
ACT.k6kill=a=>run(a,()=>{S.ui.sessKilled=1;refresh();},{ok:L('Сессия завершена','Session ended')});
SC.K07={title:()=>L('Мои данные','Your data'),render:()=>`${bar(L('Мои данные и удаление','Your data & deletion'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">
 <div class="card"><h3 class="t">${L('Скачать мои данные','Download my data')}</h3><p class="note" style="margin-bottom:12px">${L('Профиль, карта, дневник, публикации и переписка — архивом на почту. Обычно до 24 часов.','Profile, map, journal, posts and messages — an archive to your email. Usually within 24 hours.')}</p><button class="btn soft md" data-act="k7export">${I.download}${L('Запросить архив','Request archive')}</button></div>
 <div class="card" style="border-color:var(--danger-soft)"><h3 class="t" style="color:var(--danger)">${L('Удалить аккаунт','Delete account')}</h3><p class="note" style="margin-bottom:12px">${L('Профиль и интересы удалятся. Твои сообщения у собеседников сохранятся по правилам хранения. Профиль пары разъединится. Это бесплатно и не зависит от подписки.','Your profile and interests are deleted. Messages already sent stay with recipients under retention rules. A couple profile is unlinked. Free, regardless of subscription.')}</p><button class="btn danger md" data-act="k7del">${I.trash}${L('Удалить аккаунт…','Delete account…')}</button></div></div></div>`};
ACT.k7export=a=>run(a,()=>{},{ok:L('Запрос принят. Ссылка на архив придёт на почту','Request received. The archive link will be emailed to you')});
ACT.k7del=()=>{S.ui.del='';sheet(()=>({title:L('Удалить аккаунт навсегда?','Delete your account forever?'),lead:`<span class="ico l">${I.trash}</span>`,body:`<p class="lead">${L('Отменить будет нельзя. Чтобы подтвердить, введи свой ник:','This can’t be undone. To confirm, type your nickname:')} <b>${esc(S.me.nick)}</b></p><label class="field" data-field="del"><input class="inp" id="delNick" autocapitalize="off" placeholder="${esc(S.me.nick)}" autofocus></label>`,foot:`<button class="btn danger" data-act="k7do">${L('Удалить навсегда','Delete forever')}</button><button class="btn soft" data-act="closeSheet">${L('Оставить аккаунт','Keep my account')}</button>`}));};
ACT.k7do=a=>{const v=$('#delNick').value.trim();if(v!==S.me.nick){$('#delNick').classList.add('err');$('#delNick').closest('.field').classList.add('shake');toast(L('Ник не совпадает','Nickname doesn’t match'),{type:'err'});return;}run(a,()=>{closeSheet(true);const lang=S.lang;S=freshState('new');S.lang=lang;initNav();render('fade');},{ok:L('Аккаунт удалён','Account deleted')});};
SC.P12={title:()=>L('Заблокированные','Blocked'),render:()=>`${bar(L('Заблокированные','Blocked'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap"><p class="note" style="margin:0 0 12px">${L('Они не видят твой профиль и не могут писать. Разблокировка не вернёт совпадения и доступы.','They can’t see your profile or message you. Unblocking doesn’t restore matches or access.')}</p>${S.blocked.length?`<div class="card list">${S.blocked.map(b=>`<div class="li">${av(b.p,'')}<span class="tx"><b>${esc(pname(b.p))}</b><small>${L('заблокирован(а)','blocked')} ${F.rel(b.t)}</small></span><button class="btn sm soft" data-act="unblock" data-v="${b.p}">${L('Разблокировать','Unblock')}</button></div>`).join('')}</div>`:empty('block',L('Никого','No one'),L('Заблокировать можно из профиля, чата или публикации.','You can block from a profile, chat or post.'))}</div></div>`};
ACT.unblock=a=>ask({title:L(`Разблокировать ${pname(a.dataset.v)}?`,`Unblock ${pname(a.dataset.v)}?`),text:L('Человек снова сможет видеть твой профиль. Совпадение и доступы не восстановятся.','They’ll see your profile again. Matches and access won’t be restored.'),ok:L('Разблокировать','Unblock')}).then(ok=>{if(ok)run(null,()=>{S.blocked=S.blocked.filter(b=>b.p!==a.dataset.v);refresh();},{ok:L('Разблокировано','Unblocked')});});
SC.S01={title:()=>L('Помощь','Help'),render:()=>`${bar(L('Помощь и безопасность','Help & safety'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap"><div class="card list">${[['shield',L('Как прошла проверка возраста','How the age check works')],['lock',L('Кто видит мой расширенный профиль','Who sees my private profile')],['heart',L('Почему чат открывается только взаимно','Why chats open only when mutual')],['cal',L('Безопасность на офлайн-встречах','Safety at in-person events')],['crown',L('Подписка и оплата','Subscription & payment')]].map(([i,t])=>linkRow({act:'soon',icon:i,tone:'v',title:t})).join('')}</div><div class="alert warn mt16">${I.warn}<span><b>${L('Если тебе угрожают','If you’re being threatened')}</b>${L('Пожалуйся из профиля или чата и заблокируй человека. При опасности звони 112.','Report from the profile or chat and block the person. In danger, call 112.')}</span></div></div></div>`};

/* B01–B04 — Premium: never buys anyone’s consent. V7: one rich paywall used at every premium moment. */
const PLANS=()=>[['year',L('Год','Yearly'),'79,99 €',L('6,67 € в месяц','€6.67 a month'),L('−44%','−44%')],['month',L('Месяц','Monthly'),'11,99 €',L('продлевается каждый месяц','renews monthly'),'']];
// V7.1: minimal Premium while the audience grows (owner). The list is meant to be admin-configurable.
const PREM_FEATS=()=>[['undo','undo',L('Вернуть пропущенных','Bring back passed profiles'),L('Любую анкету за 7 дней — не только последнюю','Any profile from the last 7 days, not only the last one')],['history','hist',L('Вся история просмотров','Full viewing history'),L('Все, кого ты видел(а) за неделю','Everyone you saw this week')]];
const FREE_ALWAYS=()=>[L('симпатии и чат при взаимности','likes and chat when mutual'),L('запросы расширенного профиля','private profile requests'),L('все фильтры','all filters'),L('кто тебе симпатизирует','who liked you'),L('приватность, блокировки, удаление','privacy, blocking, deletion')];
function premHero(kind){const f=PREM_FEATS().find(x=>x[0]===kind);return `<div class="pw-hero"><span class="pw-crown">${I.crown}</span><b>FetUre Premium</b><p>${f?f[2]:L('Больше возможностей — то же уважение к границам','More possibilities — the same respect for boundaries')}</p><i></i><i></i></div>`;}
function premFeats(kind){return `<div class="pw-feats">${PREM_FEATS().map(([k,i,t,s])=>`<div class="pw-f ${k===kind?'on':''}"><span class="ico ${k===kind?'l':''}">${I[i]}</span><span class="tx"><b>${t}</b><small>${s}</small></span>${k===kind?`<span class="pill hot">${L('нужно сейчас','you need this')}</span>`:''}</div>`).join('')}</div><p class="note mt8">${L('Бесплатно всегда','Always free')}: ${FREE_ALWAYS().join(' · ')}.</p>`;}
function premPlans(cur){return `<div class="pw-plans">${PLANS().map(([k,t,pr,s,badge])=>`<button class="pw-plan ${cur===k?'on':''}" data-act="pwPlan" data-v="${k}" aria-pressed="${cur===k}">${badge?`<em>${badge}</em>`:''}<b>${t}</b><span class="pr">${pr}</span><small>${s}</small></button>`).join('')}</div>`;}
const planPrice=k=>PLANS().find(x=>x[0]===k)[2];
function paywall(kind,o={}){S.ui.plan=S.ui.plan||'year';sheet(()=>({title:false,body:`<div class="pw-sheet"><button class="ibtn ghost sm pw-x" data-act="closeSheet" aria-label="${L('Закрыть','Close')}">${I.close}</button>${premHero(kind)}${o.note?`<div class="alert warn mt12">${I.timer}<span>${o.note}</span></div>`:''}${premFeats(kind)}${premPlans(S.ui.plan)}</div>`,
 foot:`<button class="btn primary" data-act="bBuy" autofocus>${L(`Оформить · ${planPrice(S.ui.plan)}`,`Get Premium · ${planPrice(S.ui.plan)}`)}</button><p class="note center" style="margin:0">${L('Отмена в любой момент в магазине приложений. Premium не покупает чужое согласие.','Cancel any time in the app store. Premium never buys anyone’s consent.')} <a href="#" data-act="pwMore">${L('Подробнее','Details')}</a></p>`}),{full:false});}
ACT.pwPlan=a=>{S.ui.plan=a.dataset.v;if(cur().id==='B01')cur().plan=a.dataset.v;S.ui.sheet?resheet():refresh();};
ACT.pwMore=(a,e)=>{e?.preventDefault();closeSheet(true);go('B01');};
SC.B01={title:()=>'Premium',render:(p,r)=>{const m=S.me;r.plan=r.plan||S.ui.plan||'year';S.ui.plan=r.plan;return `${bar('',{back:1})}<div class="view nodock ${m.premium?'':'cta1'}"><div class="wrap">
 ${premHero(p.kind)}${m.premium?`<div class="alert ok mt12">${I.check}<span><b>${m.premiumGift?L('Premium в подарок','Premium as a gift'):L('Premium активен','Premium is active')}</b>${m.premiumGift?L(`от ${pname(m.premiumGift.from)} · до ${F.date(m.premiumGift.until)} · без автопродления`,`from ${pname(m.premiumGift.from)} · until ${F.date(m.premiumGift.until)} · no auto-renewal`):`${L('до','until')} ${F.date(Date.now()+30*DAY)}`}</span></div>`:''}
 <div class="sec">${L('Что даёт','What you get')}</div>${premFeats(p.kind)}
 ${m.premium?`<div class="card list mt16">${linkRow({act:'bCancel',icon:'x',title:L('Отменить продление','Cancel renewal'),sub:L('Premium останется до конца периода','Premium stays until the end of the period'),noChev:1})}${linkRow({act:'bRestore',icon:'undo',title:L('Восстановить покупки','Restore purchases'),noChev:1})}</div>`
 :`<div class="sec">${L('Тариф','Plan')}</div>${premPlans(r.plan)}<p class="note mt12">${L('Оплата через App Store или Google Play. Отменить можно в любой момент в настройках магазина.','Paid via the App Store or Google Play. Cancel any time in store settings.')}</p>`}
 <div class="sec">${L('Подарить','Gift')}</div><div class="card list">${linkRow({act:'giftPremium',icon:'crown',tone:'l',title:L('Подарить Premium другому','Gift Premium to someone'),sub:L('Точный получатель, срок на выбор, без автопродления','An exact recipient, a term you choose, no auto-renewal')})}${(S.giftsSent||[]).map(x=>`<div class="li static">${av(x.p,'sm')}<span class="tx"><b>${esc(pname(x.p))}</b><small>${esc(GIFT_PLANS().find(g=>g[0]===x.plan)[1])} · ${x.queued?L('начнётся после текущего периода','starts after their current period'):L('доставлен','delivered')}${x.anon?L(' · анонимно',' · anonymous'):''} · ${F.rel(x.t)}</small></span></div>`).join('')}</div>
 <div class="sec">${L('Честно о Premium','Honest about Premium')}</div><div class="card">${[L('Premium не поднимает тебя в подборке и не показывает чужие скрытые данные.','Premium doesn’t boost you in Discover or reveal anyone’s hidden data.'),L('Ответ на запросы, отзыв доступа и скрытие из подборки — всегда бесплатно.','Answering requests, revoking access and hiding from Discover are always free.'),L('Деньги не покупают согласие: решение всегда за человеком.','Money doesn’t buy consent: the other person always decides.')].map(x=>`<div class="fact"><i class="g">${I.check}</i><span>${x}</span></div>`).join('')}</div>
 </div></div>${m.premium?'':`<div class="ctabar"><div class="wrap"><button class="btn primary" data-act="bBuy">${L(`Оформить · ${planPrice(r.plan)}`,`Get Premium · ${planPrice(r.plan)}`)}</button></div></div>`}`;}};
ACT.bPlan=a=>ACT.pwPlan(a);
ACT.bBuy=()=>{const plan=S.ui.plan||'year';sheet(()=>({title:L('Подтверждение','Confirm'),body:`<div class="card list">${linkRow({icon:'crown',tone:'l',title:'FetUre Premium',sub:plan==='year'?L('1 год','1 year'):L('1 месяц','1 month'),val:planPrice(plan),noChev:1})}</div><p class="note mt12">${L('Подписка продлевается автоматически, пока ты её не отменишь. Списание — через магазин приложений.','The subscription renews automatically until you cancel. Charged through the app store.')}</p>`,foot:`<button class="btn dark" data-act="bPay">${I.apple}${L('Оплатить','Pay')}</button>`}));};
ACT.bPay=a=>run(a,()=>{S.me.premium=true;closeSheet();refresh();},{ms:1200,ok:L('Premium подключён. Спасибо!','Premium is on. Thank you!'),fail:L('Оплата не прошла. Деньги не списаны — попробуй ещё раз','Payment didn’t go through. You weren’t charged — try again')});
ACT.bCancel=()=>ask({title:L('Отменить продление?','Cancel renewal?'),text:L(`Premium будет работать до ${F.date(Date.now()+30*DAY)}. Выданные тебе доступы не пропадут.`,`Premium stays active until ${F.date(Date.now()+30*DAY)}. Access shared with you stays.`),ok:L('Отменить продление','Cancel renewal'),danger:true}).then(ok=>{if(ok)toast(L('Продление отменено','Renewal cancelled'),{type:'ok'});});
ACT.bRestore=a=>run(a,()=>{},{ok:L('Покупки восстановлены','Purchases restored')});
function premiumSheet(kind){paywall(kind);}


/* ---------- V10 revision part 8: photo verification and gifting Premium (prototype — no biometrics, no payment) ---------- */
/** photo verification: a selfie with a requested gesture is compared with the profile photos by a person or a service.
 *  The badge means «the photos show this person»; it is not an age or identity check and opens nothing private. */
const PV_POSES=()=>[[L('Подними ладонь рядом с лицом','Raise an open palm next to your face')],[L('Покажи два пальца у щеки','Show two fingers next to your cheek')],[L('Коснись пальцем подбородка','Touch your chin with one finger')]];
SC.V01={title:()=>L('Фото-верификация','Photo verification'),render:(p,r)=>{const m=S.me,st=m.photoCheck||'none';r.pose=r.pose??(Date.now()%3);const pose=PV_POSES()[r.pose];
 const about=`<div class="card list">${[[I.check,'g',L('Что значит значок','What the badge means'),L('Фото в профиле — действительно ты. Другие видят значок рядом с именем.','Your profile photos really show you. Others see the badge next to your name.')],[I.info,'',L('Чего он не значит','What it doesn’t mean'),L('Это не проверка возраста и не проверка документов. Значок ничего не открывает: ни чат, ни приватные фото.','It isn’t an age or ID check. The badge opens nothing: no chat, no private photos.')],[I.lock,'v',L('Что происходит с селфи','What happens to the selfie'),L('Его видит только проверка. В профиле оно не появится; после решения удаляется.','Only the review sees it. It never appears on your profile and is deleted after the decision.')]].map(([ic,t,b,s])=>`<div class="li static"><span class="ico ${t}">${ic}</span><span class="tx"><b>${b}</b><small>${s}</small></span></div>`).join('')}</div>`;
 let body='';
 if(st==='ok')body=`<div class="pv-state ok"><span class="nbadge v">${I.check}</span><b>${L('Фото подтверждено','Photo verified')}</b><p>${L(`Подтверждено ${m.photoCheckAt?F.date(m.photoCheckAt):''}. Если сменишь главное фото на фото другого человека, значок снимут.`,`Verified ${m.photoCheckAt?F.date(m.photoCheckAt):''}. If your main photo stops showing you, the badge is removed.`)}</p></div>${about}`;
 else if(st==='pending')body=`<div class="pv-state wait"><span class="ico a">${I.clock}</span><b>${L('Проверяем селфи','Checking your selfie')}</b><p>${L('Обычно до 24 часов. Сообщим в уведомлениях. Профиль работает как обычно.','Usually within 24 hours. We’ll notify you. Your profile works as usual.')}</p></div>${about}`;
 else body=`${st==='rejected'?`<div class="alert err">${I.alert}<span><b>${L('Не получилось подтвердить','We couldn’t verify it')}</b>${esc(T(m.photoCheckReason)||L('Лицо плохо видно.','The face isn’t clearly visible.'))} ${L('Попробуй ещё раз — это бесплатно.','Try again — it’s free.')}</span></div>`:''}
  <p class="lead">${L('Сделай селфи с жестом. Сравним его с фото в профиле.','Take a selfie doing the gesture. We compare it with your profile photos.')}</p>
  <div class="pv-pose"><span class="ico v" aria-hidden="true">${I.camera}</span><span><small>${L('Жест для селфи','Selfie gesture')}</small><b>${pose[0]}</b></span></div>
  <div class="card list mt12">${[L('Лицо целиком, без маски, очков от солнца и фильтров','Your whole face — no mask, sunglasses or filters'),L('Хороший свет, только ты в кадре','Good light, only you in the frame'),L('В профиле должно быть хотя бы одно фото, где видно лицо','At least one profile photo must show your face')].map(t=>`<div class="li static"><span class="ico">${I.check}</span><span class="tx"><small style="color:var(--ink);font-size:14px">${t}</small></span></div>`).join('')}</div>
  ${r.selfie?`<div class="pv-selfie mt16"><img src="${esc(r.selfie)}" alt="${L('Твоё селфи','Your selfie')}"><button class="btn text auto" data-act="pvRetake">${L('Переснять','Retake')}</button></div>`:''}
  <div class="mt16">${about}</div>`;
 const cta=st==='none'||st==='rejected'?`<div class="ctabar"><div class="wrap">${r.selfie?`<button class="btn primary" data-act="pvSend">${L('Отправить на проверку','Send for review')}</button>`:`<button class="btn primary" data-act="pvShot">${I.camera}${L('Сделать селфи','Take a selfie')}</button>`}</div></div>`:'';
 return `${bar(L('Фото-верификация','Photo verification'),{back:1,sm:1})}<div class="view nodock ${cta?'cta1':''}"><div class="wrap">${body}</div></div>${cta}`;}};
ACT.pvShot=async()=>{const r=cur(),owner=S;if(!S.me.photo){toast(L('Сначала добавь фото в профиль — сравнивать не с чем','Add a profile photo first — there’s nothing to compare with'),{type:'warn',action:{label:L('Добавить','Add'),fn:()=>go('P02')}});return;}const f=await pickLocalMedia('image/*',false);if(S!==owner||cur()!==r||!f.length)return;r.selfie=f[0].url;r.dirty=true;refresh();};
ACT.pvRetake=()=>{const r=cur();r.selfie=null;ACT.pvShot();};
ACT.pvSend=a=>{const r=cur();if(!r.selfie)return;run(a,()=>{S.me.photoCheck='pending';S.me.photoCheckReason=null;r.selfie=null;r.dirty=false;refresh();autoResolve();},{ok:L('Отправлено. Обычно проверка занимает до 24 часов','Sent. Review usually takes up to 24 hours')});};
/** QA: resolve a pending check (stands in for the reviewer) */
function pvResolve(ok){const m=S.me;if(m.photoCheck!=='pending')return toast(L('Нет проверки в ожидании','No pending check'));m.photoCheck=ok?'ok':'rejected';m.photoCheckAt=Date.now();m.photoCheckReason=ok?null:{ru:'Лицо на селфи закрыто рукой или плохо видно.',en:'The face in the selfie is covered or hard to see.'};S.notifs.unshift({id:'n'+Date.now(),type:'pv',ok,t:Date.now(),read:false,go:['V01',{}]});refresh();renderSide();}
NTXT.pv=n=>n.ok?L('<b>Фото подтверждено</b> — значок появился рядом с именем','<b>Photo verified</b> — the badge now shows next to your name'):L('<b>Фото-верификация не прошла</b> — посмотри причину и попробуй ещё раз','<b>Photo verification failed</b> — see why and try again');
NICO.pv=['verified','v'];

/* gifting Premium: an exact recipient, a term, a confirmation and an honest result. No real charge in the prototype.
 * Open product question (not decided here): a gift to someone who already has Premium is queued after their current period. */
const GIFT_PLANS=()=>[['m1',L('1 месяц','1 month'),'11,99 €',30],['m3',L('3 месяца','3 months'),'29,99 €',90],['m12',L('12 месяцев','12 months'),'79,99 €',365]];
const hasPremium=id=>{const p=person(id);return !!p&&(!!p.premium||!!S.giftedTo?.has(p));};
ACT.giftPremium=a=>{closeSheet(true);const fixed=a?.dataset?.v&&PEOPLE[a.dataset.v]?a.dataset.v:null;S.ui.gift={to:fixed,fixed:!!fixed,plan:'m1',anon:false,nick:''};sheet(giftSheet,{guard:()=>!!S.ui.gift&&!S.ui.gift.done&&(!!S.ui.gift.nick||!S.ui.gift.fixed&&!!S.ui.gift.to)});};
function giftSheet(){const g=S.ui.gift;const to=g.to&&PEOPLE[g.to]&&!isBlocked(g.to)?g.to:null;
 return{title:L('Подарить Premium','Gift Premium'),lead:`<span class="ico l">${I.crown}</span>`,body:`${to?`<div class="card list"><div class="li">${av(to,'')}<span class="tx"><b>${esc(pname(to))}${nameBadges(person(to))}</b><small>@${esc(to)}</small></span>${g.fixed?'':`<button class="btn text auto" data-act="giftChange">${L('Другой','Change')}</button>`}</div></div>`
  :`<label class="field" data-field="giftNick"><span>${L('Ник получателя','Recipient’s nickname')}</span><div class="inwrap">${I.at}<input class="inp" id="giftNick" value="${esc(g.nick)}" placeholder="mia" autocapitalize="off" spellcheck="false" data-in="giftNick" data-enter="giftFind"></div><div class="fhint">${L('Точный ник — подарок нельзя отправить «примерно».','The exact nickname — a gift can’t go to “roughly” someone.')}</div></label><button class="btn soft md" data-act="giftFind">${L('Найти','Find')}</button>`}
 ${to&&hasPremium(to)?`<div class="alert info mt12">${I.info}<span>${L(`У ${pname(to)} уже есть Premium. Подарок начнётся после окончания текущего периода — ничего не пропадёт.`,`${pname(to)} already has Premium. The gift starts after their current period ends — nothing is lost.`)}</span></div>`:''}
 ${grp(L('Срок','Term'),choices(GIFT_PLANS().map(([k,l,pr])=>[k,l,pr]),g.plan,'giftPlan'))}
 <div class="card list">${toggleRow('giftAnon',L('Не показывать, от кого','Don’t show who it’s from'),L('Получатель увидит «подарок от участника FetUre»','They’ll see “a gift from a FetUre member”'),g.anon)}</div>
 <p class="note mt12">${L('Подарок не открывает чат, симпатию или расширенный профиль — только возможности Premium у получателя. Без автопродления.','A gift doesn’t open a chat, a like or a private profile — only Premium features for the recipient. No auto-renewal.')}</p>`,
 foot:`<button class="btn primary ${to?'':'off'}" data-act="giftPay">${to?L(`Подарить · ${GIFT_PLANS().find(x=>x[0]===g.plan)[2]}`,`Gift · ${GIFT_PLANS().find(x=>x[0]===g.plan)[2]}`):L('Укажи получателя','Choose a recipient')}</button>`};}
IN.giftNick=el=>{S.ui.gift.nick=el.value;};
ACT.giftFind=()=>{const g=S.ui.gift;const v=(g.nick||'').trim().replace(/^@/,'').toLowerCase();if(!v){toast(L('Укажи ник','Enter a nickname'),{type:'err'});return;}
 if(v===(S.me.nick||'').toLowerCase()){toast(L('Себе подарить нельзя — оформи Premium обычным способом','You can’t gift yourself — get Premium the usual way'),{type:'warn'});return;}
 if(!PEOPLE[v]||isBlocked(v)){$('#giftNick')?.classList.add('err');toast(L('Такого ника нет. Проверь написание','No such nickname. Check the spelling'),{type:'err'});return;}g.to=v;resheet();};
ACT.giftChange=()=>{S.ui.gift.to=null;resheet();};
ACT.giftPlan=a=>{S.ui.gift.plan=a.dataset.v;resheet();};
ACT.giftAnon=()=>{S.ui.gift.anon=!S.ui.gift.anon;resheet();};
ACT.giftPay=a=>{const g=S.ui.gift;const to=g?.to;if(!to||!PEOPLE[to]||isBlocked(to))return;const plan=GIFT_PLANS().find(x=>x[0]===g.plan);const owner=S;
 run(a,()=>{if(S!==owner)return;g.done=true;S.giftsSent=S.giftsSent||[];S.giftsSent.unshift({p:to,plan:g.plan,anon:g.anon,t:Date.now(),queued:hasPremium(to)});S.giftedTo=S.giftedTo||new Set();S.giftedTo.add(person(to));closeSheet();S.ui.gift=null;refresh();},
  {ms:1000,ok:L(`Подарок отправлен: ${pname(to)} получит Premium на ${plan[1].toLowerCase()}. В прототипе деньги не списываются`,`Gift sent: ${pname(to)} gets Premium for ${plan[1].toLowerCase()}. No money is charged in the prototype`),fail:L('Оплата не прошла. Деньги не списаны, подарок не отправлен — попробуй ещё раз','Payment failed. You weren’t charged and the gift wasn’t sent — try again')});};
/** QA: receive a gift (the recipient's side) */
function giftReceive(){const m=S.me;const from='kai';m.premium=true;m.premiumGift={from,until:Date.now()+30*DAY};S.notifs.unshift({id:'n'+Date.now(),type:'gift',p:from,t:Date.now(),read:false,go:['B01',{}]});refresh();renderSide();toast(L('Тебе подарили Premium','You received Premium as a gift'),{type:'ok'});}
NTXT.gift=n=>L(`<b>${pname(n.p)}</b> подарил(а) тебе Premium на месяц`,`<b>${pname(n.p)}</b> gifted you Premium for a month`);
NICO.gift=['crown','l'];


/* Prototype admin setting. Live maintenance requires server/API enforcement in the main app. */
SC.MAINT={title:()=>L('Технические работы','Maintenance'),render:()=>`<div class="view nodock"><div class="wrap maintenance-screen"><span class="ico v">${I.gear}</span><h1>${L('Скоро вернёмся','We’ll be back soon')}</h1><p class="lead">${L('В FetUre идут технические работы. Попробуй зайти немного позже.','FetUre is undergoing maintenance. Please try again shortly.')}</p><p class="note">${L('Твои данные и переписка сохранятся.','Your data and conversations will be kept.')}</p><button class="btn soft auto" data-act="maintenanceRetry">${L('Проверить ещё раз','Try again')}</button></div></div>`};
ACT.maintenanceRetry=()=>{refresh();if(QA.maintenance)toast(L('Работы ещё идут','Maintenance is still in progress'),{type:'info'});};
